def breadcrumb(self):
    breadcrumb = self.name
    def get_next_parent(obj=None):
        if obj is None:
            return None
        if obj.parent:
            return obj.parent
        return None
    obj = self
    while get_next_parent(obj=obj):
        obj = get_next_parent(obj=obj)
        breadcrumb = '%s > %s' % (obj.name, breadcrumb)
    return breadcrumb

